public class DOMNodePointer_equals_TriageGen1Test {

    private Node mockNode;
    private Locale locale;

    @Before
    public void setUp() {
        mockNode = Mockito.mock(Node.class);
        locale = Locale.ENGLISH;
    }

    @Test
    public void testEquals_Reflexive() {
        DOMNodePointer pointer = new DOMNodePointer(mockNode, locale);
        // Tests: if (object == this) { return true; }
        assertTrue("Should be equal to itself", pointer.equals(pointer));
    }

    @Test
    public void testEquals_Null() {
        DOMNodePointer pointer = new DOMNodePointer(mockNode, locale);
        // Tests: if (!(object instanceof DOMNodePointer)) { return false; } via null
        assertFalse("Should not be equal to null", pointer.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        DOMNodePointer pointer = new DOMNodePointer(mockNode, locale);
        String differentObject = "Not a DOMNodePointer";
        // Tests: if (!(object instanceof DOMNodePointer)) { return false; } via different class
        assertFalse("Should not be equal to a different class", pointer.equals(differentObject));
    }

    @Test
    public void testEquals_SameNode() {
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, locale);
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, locale);
        // Tests: return node == other.node; (true case)
        assertTrue("Pointers with the same node should be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_DifferentNode() {
        Node differentNode = Mockito.mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, locale);
        DOMNodePointer pointer2 = new DOMNodePointer(differentNode, locale);
        // Tests: return node == other.node; (false case)
        assertFalse("Pointers with different nodes should not be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_UsingConstructorWithId() {
        // Coverage for different constructors ensuring node identity is preserved
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, locale, "id1");
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, locale, "id2");
        assertTrue("Pointers with same node but different IDs should still be equal via node identity", 
            pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_UsingParentPointerConstructor() {
        // Mock a NodePointer (which DOMNodePointer implements)
        // Since the constructor takes NodePointer parent, we need a dummy implementation or mock
        // In JXPath, DOMNodePointer is a NodePointer.
        DOMNodePointer parent = new DOMNodePointer(mockNode, locale);
        DOMNodePointer child = new DOMNodePointer(parent, mockNode);

        assertTrue("Child should be equal to a pointer wrapping the same node", 
            child.equals(new DOMNodePointer(mockNode, locale)));
    }
}
